    /// THE DEMO (goal bullet 2, COMPOSITE case) — PARAMETER position: a generic
    /// `fn f<T>(v: &Vec<T>) -> i32` with a trivial contract. The `&Vec<T>` parameter
    /// element is a BARE type variable, so BEFORE this change the parameter fell to
    /// the opaque `Trust.Opaque.v : Type` over-approximation. NOW it binds
    /// STRUCTURALLY at `List T` (the `Vec<T> → List T` model) under the outer
    /// `Π(T : Type)`, and the whole contract grounds + kernel-checks modulo 3 in the
    /// REAL kernel (axiom_deps EMPTY — no new carrier inductive, no 4th axiom).
    #[test]
    fn generic_vec_param_grounds_over_parameterized_sequence_carrier_modulo_3() {
        use clean_kernel::Declaration;

        use crate::reflect::reflect_contract;

        let t_param = || Ty::Unsupported {
            kind: "TyKind::Param".into(),
            detail: "generic parameter T/#0 needs monomorphization".into(),
        };
        let u64t = || Ty::Int { width: 64, signed: false };
        let vec_t = Ty::adt(
            "alloc::vec::Vec",
            vec![
                (
                    "buf".into(),
                    Ty::adt(
                        "alloc::raw_vec::RawVec",
                        vec![
                            (
                                "ptr".into(),
                                Ty::adt(
                                    "core::ptr::unique::Unique",
                                    vec![(
                                        "pointer".into(),
                                        Ty::RawPtr { mutable: false, pointee: Box::new(t_param()) },
                                    )],
                                ),
                            ),
                            ("cap".into(), u64t()),
                        ],
                    ),
                ),
                ("len".into(), u64t()),
            ],
        );
        let ref_vec_t = Ty::Ref { mutable: false, inner: Box::new(vec_t) };

        let contract = reflect_contract(
            &[("v", &ref_vec_t)],
            &Formula::Bool(true),
            "ret",
            &Ty::Int { width: 32, signed: true },
            &Formula::Bool(true),
        )
        .expect("a Vec<T> parameter contract reflects via the parameterized sequence carrier");
        // The contract is `Π(T : Type) → Π(v : List T) → Π(_ : True) → Sigma Int …`.
        let expr = to_clean_expr(&contract)
            .expect("the generic Vec<T> contract grounds in the real kernel");
        let mut env = Environment::with_prelude();
        let sort = {
            let tc = TypeChecker::new(&env);
            tc.infer_type(&expr)
                .expect("the generic Vec<T> contract type-checks in the real kernel")
        };
        let name = Name::from_string("Trust.test.generic_vec_param");
        env.add_decl(Declaration::Definition {
            name: name.clone(),
            level_params: vec![],
            type_: sort,
            value: expr,
            is_reducible: true,
        })
        .expect("the generic Vec<T> contract registers as a real kernel declaration");
        let residue = env.axiom_deps(&name).expect("declared");
        assert!(
            residue.is_empty(),
            "the generic Vec<T> parameter contract must rest on only the 3 foundational axioms; residue: {residue:?}"
        );

        // GATE — the `v` parameter's binding domain is `List (bvar 0)` (the
        // `Vec<T> → List T` model), NOT an opaque `Trust.Opaque.*` type var.
        let mut cur = contract;
        // Peel the outer Π(T:Type).
        let ProofTerm::Pi { codomain, .. } = cur else {
            panic!("expected outer Π(T:Type)");
        };
        cur = *codomain;
        // The next binder is the `v` parameter; its domain is `Slice (Var 0)`.
        let ProofTerm::Pi { domain, .. } = &cur else {
            panic!("expected Π(v : …)");
        };
        assert_eq!(
            **domain,
            ProofTerm::App(
                Box::new(ProofTerm::Const("Trust.Sort.Slice".into())),
                Box::new(ProofTerm::Var(0)),
            ),
            "the Vec<T> parameter binds at the parameterized sequence carrier Slice (Var T), not Trust.Opaque"
        );
    }

    /// RECURSIVE DEPENDENT CARRIER (goal bullet 2 tail) — a `Vec<Vec<T>>` PARAMETER and
    /// a `(T, u8)` PARAMETER now bind STRUCTURALLY in the REAL kernel modulo 3: the
    /// `Vec<Vec<T>>` param binds at `List (List T)` (the recursive `Vec → List` model),
    /// and the `(T, u8)` param at `Prod T Int` (the parameterized product) — both under
    /// the outer `Π(T : Type)`, resting on ONLY the 3 foundational axioms. This is the
    /// binding-position counterpart of `recursive_composite_fields_ground_structurally`.
    #[test]
    fn recursive_composite_params_ground_modulo_3_in_real_kernel() {
        use clean_kernel::Declaration;

        use crate::reflect::reflect_contract;

        let t_param = || Ty::Unsupported {
            kind: "TyKind::Param".into(),
            detail: "generic parameter T/#0 needs monomorphization".into(),
        };
        // Ground a one-param contract and assert it rests on only the 3 axioms.
        let ground_param = |label: &str, pty: Ty| {
            let contract = reflect_contract(
                &[("p", &pty)],
                &Formula::Bool(true),
                "ret",
                &Ty::Int { width: 32, signed: true },
                &Formula::Bool(true),
            )
            .unwrap_or_else(|e| panic!("{label} param contract reflects: {e}"));
            let expr = to_clean_expr(&contract)
                .unwrap_or_else(|| panic!("{label} param contract grounds in the real kernel"));
            let mut env = Environment::with_prelude();
            let sort = {
                let tc = TypeChecker::new(&env);
                tc.infer_type(&expr)
                    .unwrap_or_else(|e| panic!("{label} param contract type-checks: {e:?}"))
            };
            let name = Name::from_string(&format!("Trust.test.recursive_param.{label}"));
            env.add_decl(Declaration::Definition {
                name: name.clone(),
                level_params: vec![],
                type_: sort,
                value: expr,
                is_reducible: true,
            })
            .unwrap_or_else(|e| panic!("{label} registers: {e:?}"));
            let residue = env.axiom_deps(&name).expect("declared");
            assert!(residue.is_empty(), "{label} must be modulo 3; residue: {residue:?}");
        };

        // Vec<Vec<T>> (the clean `[[T]]` shape) → List (List T).
        ground_param(
            "vec_vec_t",
            Ty::Slice { elem: Box::new(Ty::Slice { elem: Box::new(t_param()) }) },
        );
        // (T, u8) → Prod T Int.
        ground_param("tuple_t_u8", Ty::Tuple(vec![t_param(), Ty::Int { width: 8, signed: false }]));
    }

    /// A `-> Point { x:u32, y:u32 }` struct return with `ensures true` grounds: the
