    /// GATE-ITER-REGION-NO-CROSS-INSTANTIATION — the mechanized carrier detector flags the
    /// iter certificate as an entry-time-indexed (single-Env-local, non-composable) handle,
    /// and does NOT flag a plain scalar ADT-return; PLUS the receiver is a `&mut` ref (the
    /// `param_is_mut_ref` decline in `sem_adt_return_opaque_shape_of` is load-bearing — a
    /// caller passing the receiver into a chained `next()` is fail-closed there).
    #[test]
    fn iter_next_value_gate_carrier_and_mut_ref_pin() {
        let func = real_iter_next();
        let shape = sem_iter_next_shape_of(&func).expect("iter shape");
        assert!(
            sem_adt_return_carries_entry_iter_handle(&shape),
            "the iter certificate carries an entry-time handle (non-composable)"
        );
        // A plain guarded scalar ADT-return does NOT carry the handle.
        let plain = crate::mirsem::SemAdtReturn {
            cond: SemCondTree::Leaf(crate::mirsem::SemCond {
                op: crate::mirsem::SemCmpOp::Lt,
                a: SemOperand::Var(0),
                b: SemOperand::Const(0),
            }),
            then_arm: SemAdtArm { variant: 1, payload: Some(SemAdtPayload::Scalar(SemOperand::Var(0))) },
            else_arm: SemAdtArm { variant: 0, payload: None },
            enum_name: "core::result::Result".to_string(),
        };
        assert!(
            !sem_adt_return_carries_entry_iter_handle(&plain),
            "a non-iter ADT-return must NOT be flagged"
        );
        // The receiver is a `&mut Iter` — the load-bearing composition fence's trigger.
        assert!(matches!(func.body.locals[1].ty, Ty::Ref { mutable: true, .. }));
    }

