    /// A `SourceSpan` copied from the dump's dispatch `SwitchInt` (for building forged terms).
    fn dump_span(func: &trust_types::VerifiableFunction) -> SourceSpan {
        func.body
            .blocks
            .iter()
            .find_map(|b| match &b.terminator {
                Terminator::SwitchInt { span, .. } => Some(span.clone()),
                _ => None,
            })
            .expect("dump has a SwitchInt span")
    }

